import java.util.*;

public class Main {
    void rightHalfPyramid(int n) {
        for (int i = 1; i <= n; i++) {              // row i needs exactly i stars
            for (int j = 0; j < i; j++) {            // print each of the i stars in this row
                System.out.print("*");                // one call per character
            }
            System.out.println();                  // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.rightHalfPyramid(4);
    }
}

